q01.sql:
-- q01: Which customers have a high share of completed orders with a known high-severity incident?
-- Synthetic coursework. Bounds [lower, as_of), Asia/Hong_Kong wall time.
SET time_zone = '+08:00';
SET @as_of = COALESCE(@as_of, TIMESTAMP('2025-11-15 12:00:00'));
SET @severity = COALESCE(@severity, 4);
SET @incident_threshold = COALESCE(@incident_threshold, 0.30);
WITH metrics AS (
 SELECT c.customer_id, c.name customer_name,
 COUNT(DISTINCT o.order_id) completed_orders,
 COUNT(DISTINCT i.incident_id) incident_events,
 COUNT(DISTINCT CASE WHEN i.severity>=@severity THEN i.incident_id END) high_severity_events,
 COUNT(DISTINCT CASE WHEN i.severity>=@severity THEN o.order_id END) affected_orders,
 GROUP_CONCAT(DISTINCT o.order_id ORDER BY o.order_id) order_ids
 FROM Customer c LEFT JOIN `order` o ON o.customer_id=c.customer_id AND o.completed_at<@as_of
 LEFT JOIN Incident i ON i.order_id=o.order_id AND i.recorded_at<@as_of
 GROUP BY c.customer_id,c.name
)
SELECT *, ROUND(affected_orders/NULLIF(completed_orders,0),4) affected_order_rate
FROM metrics WHERE affected_orders/NULLIF(completed_orders,0)>=@incident_threshold ORDER BY customer_id;

q03.sql:
-- q03: Which routes occur most often among distinct completed orders at each custody partner?
-- Synthetic coursework. Bounds [lower, as_of), Asia/Hong_Kong wall time.
SET time_zone = '+08:00';
SET @as_of = COALESCE(@as_of, TIMESTAMP('2025-11-15 12:00:00'));
SET @custody_days=COALESCE(@custody_days,14);
SET @top_routes=COALESCE(@top_routes,5);
WITH route_counts AS (
 SELECT pc.partner_name,e.pickup_location,e.dropoff_location,COUNT(DISTINCT e.order_id) order_count,
 COUNT(*) custody_episodes,GROUP_CONCAT(DISTINCT e.order_id ORDER BY e.order_id) order_ids
 FROM ParkingCustody pc JOIN v_order_evidence e ON e.assignment_id=pc.assignment_id
 WHERE e.completed_at<@as_of AND pc.check_in_time>=DATE_SUB(@as_of,INTERVAL @custody_days DAY) AND pc.check_in_time<@as_of
 GROUP BY pc.partner_name,e.pickup_location,e.dropoff_location
), ranked AS (
 SELECT *,ROW_NUMBER() OVER (PARTITION BY partner_name ORDER BY order_count DESC,pickup_location,dropoff_location) route_rank FROM route_counts
)
SELECT * FROM ranked WHERE route_rank<=@top_routes ORDER BY partner_name,route_rank;

q07.sql:
-- q07: How do service-type rating means compare when review coverage is visible?
-- Synthetic coursework. Bounds [lower, as_of), Asia/Hong_Kong wall time.
SET time_zone = '+08:00';
SET @as_of = COALESCE(@as_of, TIMESTAMP('2025-11-15 12:00:00'));
SELECT service_type,COUNT(*) completed_orders,COUNT(CASE WHEN rated_at<@as_of THEN rating_id END) review_count,
 ROUND(COUNT(CASE WHEN rated_at<@as_of THEN rating_id END)/COUNT(*),4) review_coverage,
 ROUND(AVG(CASE WHEN rated_at<@as_of THEN stars END),2) avg_rating,
 MIN(CASE WHEN rated_at<@as_of THEN stars END) min_rating,MAX(CASE WHEN rated_at<@as_of THEN stars END) max_rating,
 GROUP_CONCAT(order_id ORDER BY order_id) order_ids
FROM v_order_evidence WHERE completed_at<@as_of GROUP BY service_type ORDER BY avg_rating DESC,service_type;

q08.sql:
-- q08: Which customers repeat positive-net settled purchases, and how does that differ from vehicle reuse?
-- Synthetic coursework. Bounds [lower, as_of), Asia/Hong_Kong wall time.
SET time_zone = '+08:00';
SET @as_of = COALESCE(@as_of, TIMESTAMP('2025-11-15 12:00:00'));
SET @purchase_months=COALESCE(@purchase_months,3);
WITH paid_orders AS (
 SELECT * FROM v_order_evidence WHERE completed_at<@as_of
 AND request_time>=DATE_SUB(@as_of,INTERVAL @purchase_months MONTH) AND request_time<@as_of
 AND payment_time<@as_of AND final_fee-CASE WHEN refund_time<@as_of THEN refund_amount ELSE 0 END>0
), stats AS (
 SELECT c.customer_id,c.name customer_name,c.membership_tier,COUNT(*) paid_orders,
 COUNT(DISTINCT e.vehicle_id) vehicle_count,SUM(e.final_fee-CASE WHEN e.refund_time<@as_of THEN e.refund_amount ELSE 0 END) net_paid_asof,
 GROUP_CONCAT(e.order_id ORDER BY e.order_id) order_ids
 FROM Customer c JOIN paid_orders e ON e.customer_id=c.customer_id GROUP BY c.customer_id,c.name,c.membership_tier
)
SELECT *,ROUND((paid_orders-1)/paid_orders,4) repeat_order_share,
 ROUND((paid_orders-vehicle_count)/paid_orders,4) extra_vehicle_order_share FROM stats WHERE paid_orders>1
ORDER BY repeat_order_share DESC,customer_id;

q09.sql:
-- q09: What is the registered fleet distribution, including models with zero vehicles?
-- Synthetic coursework. Bounds [lower, as_of), Asia/Hong_Kong wall time.
SET time_zone = '+08:00';
SET @as_of = COALESCE(@as_of, TIMESTAMP('2025-11-15 12:00:00'));
SELECT b.id brand_id,b.name brand_name,m.id model_id,m.name model_name,COUNT(v.vehicle_id) vehicle_count,
 GROUP_CONCAT(v.vehicle_id ORDER BY v.vehicle_id) vehicle_ids
FROM Brandmodel b JOIN Brandmodel m ON m.parent_id=b.id
LEFT JOIN Vehicle v ON v.model_id=m.id AND v.registered_at<@as_of
GROUP BY b.id,b.name,m.id,m.name ORDER BY brand_id,model_id;

q10.sql:
-- q10: Which completed services in seven days remain unsettled for strictly more than 24 hours?
-- Synthetic coursework. Bounds [lower, as_of), Asia/Hong_Kong wall time.
SET time_zone = '+08:00';
SET @as_of = COALESCE(@as_of, TIMESTAMP('2025-11-15 12:00:00'));
SET @unpaid_days=COALESCE(@unpaid_days,7);
SET @overdue_hours=COALESCE(@overdue_hours,24);
SELECT e.order_id,e.customer_id,c.name customer_name,e.completed_at,e.quoted_fee,
 CASE WHEN e.payment_id IS NULL THEN 'missing' ELSE 'pending' END payment_state_asof,
 ROUND(TIMESTAMPDIFF(SECOND,e.completed_at,@as_of)/3600,4) hours_since_completion,
 e.order_id AS order_ids
FROM v_order_evidence e JOIN Customer c ON c.customer_id=e.customer_id
WHERE e.completed_at>=DATE_SUB(@as_of,INTERVAL @unpaid_days DAY) AND e.completed_at<@as_of
 AND e.completed_at<DATE_SUB(@as_of,INTERVAL @overdue_hours HOUR)
 AND (e.payment_id IS NULL OR e.payment_time IS NULL OR e.payment_time>=@as_of)
ORDER BY e.completed_at,e.order_id;
